// IP-based rate limiting (Kostenairbag): 3 recipes per IP per day, 12 system-wide.
const store = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);
if (store.day !== today) { store.day = today; store.perIp = {}; store.total = 0; }
const headers = $json.headers || {};
const forwarded = headers['x-forwarded-for'] || headers['x-real-ip'] || 'unknown';
const ip = String(forwarded).split(',')[0].trim();
const IP_LIMIT = 3;
const SYSTEM_LIMIT = 12;
const usedByIp = store.perIp[ip] || 0;
const exceeded = usedByIp >= IP_LIMIT || (store.total || 0) >= SYSTEM_LIMIT;
if (!exceeded) { store.perIp[ip] = usedByIp + 1; store.total = (store.total || 0) + 1; }
const remaining = Math.max(0, IP_LIMIT - (store.perIp[ip] || usedByIp));
return [{ json: { ...$json, ip, exceeded, remaining } }];

